WITH history AS (SELECT DATE_TRUNC('DAY', "EVENT_DATE") AS period, COUNT(*) AS cnt FROM "FAKE_PROJECT"."DATASET"."ORDERS" WHERE "EVENT_DATE" >= '2026-05-01'::DATE - INTERVAL '28 DAY' AND "EVENT_DATE" < '2026-05-01'::DATE GROUP BY period) SELECT PERCENTILE_CONT(0.05) WITHIN GROUP (ORDER BY cnt) AS p_lo, PERCENTILE_CONT(0.95) WITHIN GROUP (ORDER BY cnt) AS p_hi, COUNT(*) AS n FROM history